from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class TnlParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_templateUsage()

    def set_templateUsage(self):
        if self.mo_num == '1' or self.mo_num == '2' or self.mo_num == '3':
            self.set_parameter('templateUsage', 'TRUE')
        else:
            self.set_parameter('templateUsage', 'FALSE')
            if self.is_sa_nsa:
                self.set_parameter('userLabel', self.mo)
